from flask import Flask, request, render_template_string, send_file, redirect, url_for
from io import BytesIO
from datetime import datetime
import re, os, json
app = Flask(__name__)
app.config['MAX_CONTENT_LENGTH'] = 1024 * 1024

RULES = [
('SQL01','Possible SQL injection','High',r'execute\s*\(\s*(f[\'\"]|[\'\"])','The query appears to be built by inserting text into SQL. If that text includes user input, an attacker may change what the query does.','Use a parameterized query: cursor.execute("SELECT * FROM users WHERE name = ?", (username,)). The placeholder depends on your database driver.','SQL injection'),
('EVAL01','Use of eval()','High',r'\beval\s*\(','eval() runs Python expressions from text. If a user can control that text, it may run unintended code.','Avoid eval() for user input. Use json.loads() for JSON or validate expected values explicitly.','Unsafe evaluation'),
('CMD01','Shell command risk','High',r'subprocess\.(run|Popen|call|check_output)\s*\([^\n]*shell\s*=\s*True','shell=True lets the operating system shell interpret the command. Combining it with untrusted input can be dangerous.','Prefer a list of arguments with shell=False, validate input, and set a timeout.','Command execution'),
('SECRET01','Possible hard-coded secret','High',r'(?i)\b(password|passwd|api[_-]?key|secret|token)\b\s*=\s*[\'\"][^\'\"]{4,}[\'\"]','A real password or token stored in source code can leak if the file is shared or committed. Demo values can also trigger this rule.','Load real secrets from environment variables or a secret manager. Rotate any real secret that was exposed.','Secrets'),
('DEBUG01','Debug mode enabled','Medium',r'(?i)debug\s*=\s*True','Debug mode can reveal detailed internal errors if enabled in production.','Turn debug mode off in production and show safe error messages.','Configuration'),
('HASH01','Weak hash function reference','Medium',r'\b(md5|sha1)\s*\(','MD5 and SHA-1 are unsuitable for many security-sensitive uses. Context matters.','For passwords, use a dedicated password-hashing library. Choose a modern hash for integrity checks.','Cryptography'),
('PICKLE01','Pickle deserialization','High',r'pickle\.loads?\s*\(','Loading untrusted pickle data can execute code during deserialization.','Do not unpickle untrusted data. Prefer JSON with validation for data exchange.','Deserialization'),
('TLS01','TLS verification disabled','High',r'verify\s*=\s*False','Disabling certificate checks can allow an HTTPS connection to be intercepted.','Keep certificate verification enabled and fix certificate configuration instead.','Transport security'),
]
SAMPLE='''import subprocess\nimport sqlite3\nPASSWORD = "demo-password-12345"  # training example only\nDEBUG = True\ndef find_user(username):\n    conn = sqlite3.connect("example.db")\n    query = f"SELECT * FROM users WHERE name = '{username}'"\n    return conn.execute(query).fetchall()\ndef run_command(user_value):\n    return subprocess.run("echo " + user_value, shell=True)\n'''
STATE={'filename':'','source':'','findings':[],'lines':0}

def scan_source(source):
    out=[]
    for n,line in enumerate(source.splitlines(),1):
        if not line.strip() or line.strip().startswith('#'): continue
        for rid,title,sev,pat,why,fix,cat in RULES:
            if re.search(pat,line):
                out.append({'id':rid,'title':title,'severity':sev,'line':n,'snippet':line.strip()[:220],'why':why,'fix':fix,'category':cat})
    return out

